package analyzerstructured

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"io"
	"strings"
	"testing"
)

// pinnedBeamfallBlobCorpus is a complete, compressed literal of the ten
// immutable Git blobs named below. Tests never read a Beamfall checkout.
const pinnedBeamfallBlobCorpus = ``

func TestPinnedBeamfallDogfoodBlobCorpus(t *testing.T) {
	bodies := decodePinnedBeamfallBlobCorpus(t)
	cases := []struct {
		profile                     FormatProfile
		path, digest, revision, why string
	}{
		{PropertiesProfile, "gradle.properties", "f37de70e9ddb470b6f286d0c6173e71be72cb9e8", "beamfall-android-ui@6e379d7feec88128439d1753325bcfb22194fdfc", ""},
		{JSONLProfile, "contracts/export/v1/fixtures/full-state/records/library.jsonl", "0a6acd1fb9fc8b4e000214a3cc2234a6c3b4e058", "beamfall@da38c59eb30b2121cbac37b912485b30b2e54841", ""},
		{HCLProfile, "docker-bake.hcl", "703bfd80e42eccf0131519dc9c276a051bafcf1a", "beamfall@da38c59eb30b2121cbac37b912485b30b2e54841", "UNSUPPORTED_SCHEMA"},
		{XMLProfile, "packaging/unraid/beamfall-core.xml", "eb2689ebffa427fc87bafa325b171d2dad57d302", "beamfall@da38c59eb30b2121cbac37b912485b30b2e54841", ""},
		{WebManifestProfile, "internal/web/app/public/manifest.webmanifest", "3e652e990e320eaeb850cc342a7d11133ea754a6", "beamfall@da38c59eb30b2121cbac37b912485b30b2e54841", ""},
		{SVGProfile, "internal/web/app/public/manifest-icon.svg", "12cc99b3c3692462217eabf610638dfde58fb61a", "beamfall@da38c59eb30b2121cbac37b912485b30b2e54841", ""},
		{XMLProfile, "kit/src/androidTest/AndroidManifest.xml", "3e9e4647b0ef36b19e9d7b639de7252b29aa7d54", "beamfall-android-ui@6e379d7feec88128439d1753325bcfb22194fdfc", "UNSUPPORTED_SCHEMA"},
		{TOMLProfile, "gradle/libs.versions.toml", "442e4c36346c40995a7c88a3b5326ee671a68fb8", "beamfall-android-ui@6e379d7feec88128439d1753325bcfb22194fdfc", "UNSUPPORTED_SCHEMA"},
		{PlistProfile, "Apps/BeamfallMobile/Info.plist", "5c9d018cb19babfd24cd74adcaef1b96e5812872", "beamfall-apple@8588cec3dedaef63bbff458e5e7c8bb6335de107", "UNSUPPORTED_SCHEMA"},
		{XMLProfile, "gradle/verification-metadata.xml", "e0b4eabe37b8c8787ed1d51b1498da1889a9f4ad", "beamfall-android-ui@6e379d7feec88128439d1753325bcfb22194fdfc", "LIMIT_EXCEEDED"},
	}
	if len(bodies) != len(cases) {
		t.Fatalf("literal corpus bodies=%d want=%d", len(bodies), len(cases))
	}
	for index, tc := range cases {
		t.Run(tc.revision+":"+tc.path, func(t *testing.T) {
			if got := sha1Text(bodies[index]); got != tc.digest {
				t.Fatalf("literal blob digest=%s want=%s", got, tc.digest)
			}
			output := string(Analyze(testFrame(t, testInput("input-1", tc.profile, tc.path, bodies[index]))))
			if tc.why == "" && !strings.Contains(output, `"status":"CANDIDATE"`) {
				t.Fatalf("unexpected rejection: %s", output)
			}
			if tc.why != "" && !strings.Contains(output, `"reason":"`+tc.why+`"`) {
				t.Fatalf("unexpected result: %s", output)
			}
		})
	}
}

func decodePinnedBeamfallBlobCorpus(t *testing.T) []string {
	t.Helper()
	compressed, err := base64.StdEncoding.DecodeString(pinnedBeamfallBlobCorpus)
	if err != nil {
		t.Fatal(err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		t.Fatal(err)
	}
	raw, err := io.ReadAll(reader)
	if err != nil {
		t.Fatal(err)
	}
	if err := reader.Close(); err != nil {
		t.Fatal(err)
	}
	return strings.Split(string(raw), "\x00")
}
